    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int> points(N);
    for (int i = 0; i < N; i++) cin >> points[i];

    // remaining matches: for i<j
    vector<pair<int,int>> matches;
    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            matches.emplace_back(i, j);
        }
    }
    int M = matches.size();

    // If no matches left
    if (M == 0) {
        // all points already equal?
        bool allEqual = true;
        for (int i = 1; i < N; i++) if (points[i] != points[0]) allEqual = false;
        cout << (allEqual ? 1 : 0) << "\n";
        return 0;
    }

    // DP over matches
    // We'll use recursion + memoization for simplicity
    // State: (matchIndex, currentPoints)
    // But points can be up to 100 + M*3, so map is okay.

    map<vector<int>, int> memo;
    function<int(int, vector<int>&)> dfs = [&](int idx, vector<int>& cur) -> int {
        if (idx == M) {
            // check all equal
            for (int i = 1; i < N; i++) if (cur[i] != cur[0]) return 0;
            return 1;
        }
        auto key = cur;
        key.push_back(idx);
        if (memo.count(key)) return memo[key];

        auto [a, b] = matches[idx];
        int total = 0;

        // a wins
        cur[a] += 3;
        total += dfs(idx + 1, cur);
        cur[a] -= 3;

        // b wins
        cur[b] += 3;
        total += dfs(idx + 1, cur);
        cur[b] -= 3;

        // draw
        cur[a] += 1;
        cur[b] += 1;
        total += dfs(idx + 1, cur);
        cur[a] -= 1;
        cur[b] -= 1;

        return memo[key] = total;
    };

    vector<int> cur = points;
    cout << dfs(0, cur) << "\n";
    return 0;
}

