 * This program solves the standard interpretation of the task:
 *
 * - There are n teams in a single round-robin tournament.
 * - Some matches may already be decided.
 * - Remaining matches have only two outcomes: one team wins, the other loses.
 * - We count how many assignments of outcomes to the remaining matches make all
 *   teams finish with the same number of wins, i.e. a full playoff among all teams.
 *
 * Assumed input format:
 *   n
 *   n lines, each a string of length n describing the table
 *
 * Characters:
 *   'W' : row team already beat column team
 *   'L' : row team already lost to column team
 *   '.' or '?' or '-' : match not yet decided
 *   diagonal can be any non-W/L character
 *
 * If your judge uses a different but equivalent undecided marker, this code
 * accepts '.', '?', and '-'.
 *
 * Output:
 *   the number of valid completions
 *
 * Method:
 *   Let target wins per team be (n-1)/2. If n is even, impossible.
 *   Compute current wins and the list of undecided matches.
 *   We need to orient each undecided edge so every vertex reaches target outdegree.
 *
 *   This is counted by DP over subsets:
 *     dp[mask] = number of ways after processing some undecided matches so that
 *                the set bits are teams that have received a win from processed matches.
 *   More directly, for each undecided match (a,b), we choose either a or b to
 *   receive one additional win.
 *
 *   To keep only feasible states, team i may receive exactly need[i] wins from
 *   undecided matches, where need[i] = target - currentWins[i].
 *
 *   We encode counts by subset expansion only when each team needs at most 1?
 *   That is not enough in general.
 *
 *   So instead we use memoized DFS over matches with pruning, storing the vector
 *   of remaining needs in mixed radix form.
 *
 *   This is exponential in the number of teams / undecided matches, but is the
 *   natural exact approach for small/medium constraints typical for this classic
 *   counting problem.
 */
public class Main {
    static int n;
    static char[][] g;
    static int[] need;
    static int[][] matches;
    static HashMap<Long, Long> memo = new HashMap<>();

    static long encode(int idx, int[] rem) {
        long key = idx;
        long base = matches.length + 1L;
        for (int x : rem) key = key * base + x;
        return key;
    }

    static long dfs(int idx, int[] rem) {
        if (idx == matches.length) {
            for (int x : rem) if (x != 0) return 0;
            return 1;
        }

        long key = encode(idx, rem);
        Long got = memo.get(key);
        if (got != null) return got;

        int a = matches[idx][0];
        int b = matches[idx][1];
        long ans = 0;

        if (rem[a] > 0) {
            rem[a]--;
            ans += dfs(idx + 1, rem);
            rem[a]++;
        }
        if (rem[b] > 0) {
            rem[b]--;
            ans += dfs(idx + 1, rem);
            rem[b]++;
        }

        memo.put(key, ans);
        return ans;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String first;
        do {
            first = br.readLine();
            if (first == null) return;
            first = first.trim();
        } while (first.isEmpty());

        n = Integer.parseInt(first);
        g = new char[n][];
        for (int i = 0; i < n; i++) {
            String s = br.readLine();
            while (s != null && s.length() < n) {
                String t = br.readLine();
                if (t == null) break;
                s += t;
            }
            g[i] = s.toCharArray();
        }

        if ((n & 1) == 0) {
            System.out.println(0);
            return;
        }

        int target = (n - 1) / 2;
        int[] wins = new int[n];
        ArrayList<int[]> list = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                char a = g[i][j];
                char b = g[j][i];
                if (a == 'W' || b == 'L') {
                    wins[i]++;
                } else if (a == 'L' || b == 'W') {
                    wins[j]++;
                } else {
                    list.add(new int[]{i, j});
                }
            }
        }

        need = new int[n];
        for (int i = 0; i < n; i++) {
            need[i] = target - wins[i];
            if (need[i] < 0) {
                System.out.println(0);
                return;
            }
        }

        int sumNeed = 0;
        for (int x : need) sumNeed += x;
        if (sumNeed != list.size()) {
            System.out.println(0);
            return;
        }

        matches = list.toArray(new int[0][]);

        // Simple pruning: if a team needs more wins than undecided matches incident to it.
        int[] undecDeg = new int[n];
        for (int[] e : matches) {
            undecDeg[e[0]]++;
            undecDeg[e[1]]++;
        }
        for (int i = 0; i < n; i++) {
            if (need[i] > undecDeg[i]) {
                System.out.println(0);
                return;
            }
        }

        long ans = dfs(0, need.clone());
        System.out.println(ans);
    }
